#!/usr/bin/python
import sys


def read_total(path):
    total = 0
    with open(path) as counters:
        for number, line in enumerate(counters, 1):
            value = line.strip()
            if not value or not value.isascii() or not value.isdigit():
                raise ValueError("invalid counter on line %d" % number)
            total += int(value, 10)
    return total


try:
    total = read_total(sys.argv[1])
except (IndexError, OSError, ValueError) as error:
    sys.stderr.write("total.py: %s\n" % error)
    sys.exit(1)

sys.stdout.write(str(total) + "\n")
